contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 h, uint amount, bool doSecond) public payable {
        require(address(this).balance >= amount, "insufficient balance");

        // first lock-in: fresh sender, so block is 0 => succeeds when amount == 1 ether
        bool firstReverted;
        try c.lockInGuess{value: amount}(h) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        if (doSecond) {
            // second lock-in: block is now nonzero (or guessed is set) => must revert regardless of amount
            bool secondReverted;
            try c.lockInGuess{value: amount}(h) {
                secondReverted = false;
            } catch {
                secondReverted = true;
            }

            assert(amount == 1 ether ? !firstReverted : firstReverted);
            assert(secondReverted || firstReverted);
            return;
        }

        assert(amount == 1 ether ? !firstReverted : firstReverted);
    }

    receive() external payable {}
}

